// Runtime compiled-route engine.
//
// Routes a prompt through a hub's compiled policy using the same proven closed
// decision algebra the shadow canary validates (evaluateCanary over the hub's
// snapshot). The engine routes WITHIN a hub — it selects compiled destinations
// (modes/surfaces) when the prompt carries the policy's detector signals, and
// otherwise returns a `defer` decision (the correct conservative outcome), so a
// caller can fall back to legacy routing on ambiguous input.
//
// This module is pure and side-effect-free: it never flips serving authority
// and never edits a manifest. Whether its result is authoritative is decided by
// the resolver, which gates on the activation manifest and a runtime flag.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Each hub's compiled policy + engine live in its shadow rollout child; this
// phase reuses them read-only rather than duplicating the compiled contract.
const IMPL_ROOT = path.resolve(__dirname, '..', '..');

// Promoted activation manifests (never the spec tree). Fingerprinting a hub's
// manifest lets the engine cache invalidate when the manifest flips, so a
// serving-authority or selected-policy change never serves an engine cached
// against the prior manifest.
const ACTIVATION_ROOT = path.resolve(__dirname, '..', '..', '013-live-activation', 'activation');
const HUB_CHILD = Object.freeze({
  'sk-code': '009-parent-hub-rollout/001-sk-code',
  'system-deep-loop': '009-parent-hub-rollout/002-system-deep-loop',
  'mcp-tooling': '009-parent-hub-rollout/003-mcp-tooling',
  'cli-external-orchestration': '009-parent-hub-rollout/004-cli-external-orchestration',
  'cli-classifier': '009-parent-hub-rollout/008-cli-classifier',
  'sk-doc': '009-parent-hub-rollout/007-sk-doc',
  'sk-design': '009-parent-hub-rollout/009-sk-design',
});

const engineCache = new Map();

// Fingerprint the hub's activation manifest. A read failure yields a stable
// sentinel so a route never throws on a missing or unreadable manifest; the
// downstream HUB_CHILD check still rejects an unknown hub.
function manifestFingerprint(hubId) {
  try {
    return crypto.createHash('sha256')
      .update(fs.readFileSync(path.join(ACTIVATION_ROOT, hubId, 'manifest.json')))
      .digest('hex');
  } catch {
    return 'no-manifest';
  }
}

function loadHubEngine(hubId) {
  // Key on the manifest fingerprint so a flip invalidates a stale cached engine
  // while an unchanged manifest still hits the cache within a process.
  const cacheKey = `${hubId}::${manifestFingerprint(hubId)}`;
  if (engineCache.has(cacheKey)) return engineCache.get(cacheKey);
  const child = HUB_CHILD[hubId];
